// @vitest-environment node
import { describe, expect, it } from "vitest";
import v2 from "./patterns.v2.contract.json";
import v1 from "../../../content/contracts/patterns.json";
import type { InsightRow } from "./insights";
import { patterns, routinePatterns, type RoutineItem } from "./patterns";

// patterns.json version 2 (1.4 F), generated by scripts/gen-patterns-v2.mjs for moodbow-app's
// feat/routine-038. Until it's on the app's master and synced into content/contracts, the draft
// lives here; then this test moves to patterns.test.ts.
type RoutineCase = { name: string; rows: InsightRow[]; routine: RoutineItem[]; expect: unknown };

describe("patterns.json v2: version 1 is unchanged inside it", () => {
  it("the same rules, today and cases", () => {
    expect(v2.rules).toEqual(v1.rules);
    expect(v2.today).toBe(v1.today);
    expect(v2.cases).toEqual(v1.cases);
    for (const c of v2.cases as unknown as { rows: InsightRow[]; expect: unknown }[]) expect(patterns(c.rows, v2.today)).toEqual(c.expect);
  });
});

describe("patterns.json v2: routine", () => {
  for (const c of v2.routineCases as unknown as RoutineCase[]) {
    it(c.name, () => {
      expect(routinePatterns(c.rows, v2.today, c.routine)).toEqual(c.expect);
    });
  }

  it("never a lower or same line: only shown carries numbers", () => {
    for (const c of v2.routineCases as unknown as RoutineCase[])
      for (const p of routinePatterns(c.rows, v2.today, c.routine)) {
        if (p.state === "shown") expect(p.diff).toBeGreaterThanOrEqual(v2.rules.sameBelow);
        else expect([p.a, p.b, p.diff]).toEqual([null, null, null]);
      }
  });

  it("the footnote warns about medication", () => {
    expect(v2.copy.routineFootnote).toMatch(/medication/);
  });
});
